def shoot(x):
    def score(shots, bonus):
        hits = shots.count('X')
        return hits * 2 if bonus else hits

    pete_total = 0
    phil_total = 0

    for round in x:
        round_data, bonus = round
        pete_total += score(round_data['P1'], bonus)
        phil_total += score(round_data['P2'], bonus)

    if pete_total > phil_total:
        return 'Pete Wins!'
    elif phil_total > pete_total:
        return 'Phil Wins!'
    else:
        return 'Draw!'
